styles:
.page-case .case-hero { padding-top: clamp(150px, 20vh, 240px); padding-bottom: clamp(28px, 4vw, 56px); }
.page-case .case-eyebrow { color: var(--red); font-size: clamp(15px, 1.3vw, 19px); letter-spacing: .04em; text-transform: uppercase; margin-bottom: clamp(16px, 2.4vw, 30px); }
.page-case .case-title { font-size: clamp(48px, 8.4vw, 132px); line-height: 1.02; color: var(--grey-700); letter-spacing: -0.01em; max-width: 14ch; }

.page-case .case-tags { display: flex; flex-wrap: wrap; gap: 8px; margin-top: clamp(22px, 3vw, 34px); }
.page-case .case-tag {
  font-size: 13px; color: var(--red); line-height: 1;
  border: 1px solid #f2c9c9; background: #fff5f5;
  border-radius: 999px; padding: 8px 14px; letter-spacing: .01em;
}

.page-case .case-meta {
  display: flex; flex-wrap: wrap; gap: 12px 34px; margin-top: clamp(24px, 3vw, 36px);
  padding-top: clamp(20px, 2.4vw, 30px); border-top: 1px solid var(--line);
}
.page-case .case-meta__item { display: flex; flex-direction: column; gap: 4px; }
.page-case .case-meta__k { font-size: 12px; letter-spacing: .12em; text-transform: uppercase; color: var(--grey-500); }
.page-case .case-meta__v { font-family: var(--font-display); font-size: clamp(17px, 1.5vw, 22px); color: var(--grey-900); line-height: 1.1; }

.page-case .case-cover { margin-top: clamp(30px, 4vw, 56px); border-radius: var(--radius-lg); overflow: hidden; background: var(--bg-alt); }
.page-case .case-cover img { width: 100%; height: clamp(260px, 46vw, 720px); object-fit: cover; }

.page-case .case-lead {
  max-width: 40ch; font-size: clamp(22px, 2.6vw, 38px); line-height: 1.3;
  color: var(--grey-700); font-family: var(--font-display);
}
.page-case .case-lead-wrap { display: grid; grid-template-columns: 1fr 1.2fr; gap: clamp(28px, 5vw, 90px); align-items: start; }
.page-case .case-lead-body { color: var(--grey-700); font-size: clamp(16px, 1.2vw, 19px); }
.page-case .case-lead-body p + p { margin-top: 1em; }

.page-case .case-block { max-width: 78ch; }
.page-case .case-block + .case-block { margin-top: clamp(44px, 6vw, 90px); }
.page-case .case-h { font-size: clamp(30px, 4vw, 58px); color: var(--red); line-height: 1.02; margin-bottom: clamp(18px, 2vw, 28px); }
.page-case .case-p { color: var(--grey-700); font-size: clamp(16px, 1.2vw, 19px); }
.page-case .case-p + .case-p { margin-top: 1em; }

.page-case .case-steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: clamp(18px, 2vw, 30px); }
.page-case .case-step {
  border: 1px solid var(--line); border-radius: var(--radius-lg);
  padding: clamp(24px, 2.2vw, 38px); display: flex; flex-direction: column; gap: 16px;
  transition: box-shadow .4s var(--ease), transform .4s var(--ease), border-color .4s var(--ease);
}
.page-case .case-step:hover { box-shadow: 0 20px 50px rgba(0,0,0,.06); transform: translateY(-4px); border-color: #eecccc; }
.page-case .case-step__num { font-family: var(--font-display); font-size: clamp(34px, 3vw, 48px); color: var(--red); line-height: 1; }
.page-case .case-step__title { font-family: var(--font-display); font-size: clamp(20px, 1.8vw, 26px); color: var(--grey-900); line-height: 1.1; }
.page-case .case-step__list { display: flex; flex-direction: column; gap: 10px; color: var(--grey-700); font-size: clamp(15px, 1.05vw, 17px); }
.page-case .case-step__list li { position: relative; padding-left: 20px; line-height: 1.5; }
.page-case .case-step__list li::before { content: ""; position: absolute; left: 0; top: .62em; width: 8px; height: 8px; border-radius: 50%; background: var(--red); }

.page-case .case-figure { margin-block: clamp(44px, 6vw, 90px); border-radius: var(--radius-lg); overflow: hidden; background: var(--bg-alt); }
.page-case .case-figure img { width: 100%; height: clamp(240px, 40vw, 620px); object-fit: cover; }

.page-case .case-cols { display: grid; grid-template-columns: repeat(2, 1fr); gap: clamp(28px, 4vw, 70px); align-items: start; }
.page-case .case-list { display: flex; flex-direction: column; gap: 16px; }
.page-case .case-list li { position: relative; padding-left: 26px; color: var(--grey-700); font-size: clamp(16px, 1.15vw, 18px); line-height: 1.5; }
.page-case .case-list li strong { color: var(--grey-900); font-weight: 400; }
.page-case .case-list li::before {
  content: ""; position: absolute; left: 0; top: .5em; width: 12px; height: 12px;
  border: 2px solid var(--red); border-radius: 50%;
}

.page-case .case-why {
  background: var(--bg-alt); border-radius: var(--radius-lg);
  padding: clamp(32px, 5vw, 80px);
}
.page-case .case-why .case-h { max-width: none; }
.page-case .case-why .case-p { max-width: 70ch; }

.page-case .case-back {
  display: inline-flex; align-items: center; gap: 12px;
  font-family: var(--font-display); font-size: clamp(18px, 1.6vw, 24px); color: var(--grey-900);
  border: 1px solid var(--grey-300); border-radius: 999px; padding: 12px 24px;
  transition: border-color .3s var(--ease), color .3s var(--ease);
}
.page-case .case-back:hover { border-color: var(--red); color: var(--red); }
.page-case .case-back .arrow { color: var(--red); display: inline-flex; }

@media (max-width: 900px) {
  .page-case .case-lead-wrap { grid-template-columns: 1fr; }
  .page-case .case-steps { grid-template-columns: 1fr; }
  .page-case .case-cols { grid-template-columns: 1fr; }
}
